 * deleted) has it as its current slug, and no other workspace still holds it
 * retired. The org's own retired slugs are always available to it.
 */
export async function isOrgSlugAvailableTo(
  slug: string,
  orgId: OrgId,
): Promise<boolean> {
  const current = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(eq(organizations.slug, slug))
    .get();
  if (current && current.id !== orgId) return false;

  return heldRetiredSlugRows(slug).every((held) => held.orgId === orgId);
}

/**
