import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { subscribe } from "@/lib/event-bus";
import { InvalidSlugError } from "@/lib/slug";
import { PermissionDeniedError } from "@/lib/permissions";
import * as orgService from "@/server/services/organization-service";
import * as sessionService from "@/server/services/session-service";
import * as activityService from "@/server/services/activity-service";
import { createTenant, useTemporaryDatabase } from "$P/tests/server/_support/fixtures";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("rename", () => {
  it("works", async () => {
    const a = await createTenant("alpha");
    const b = await createTenant("beta");
    const seen: unknown[] = [];
    const off = subscribe("organization.slug_changed", (p) => { seen.push(p); });

    await expect(orgService.renameOrganizationSlug(a.actors.member, { orgId: a.org.id, slug: "zzz" })).rejects.toBeInstanceOf(PermissionDeniedError);
    const same = await orgService.renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "alpha" });
    expect(same).toEqual(a.org);
    expect(seen).toHaveLength(0);
    await expect(orgService.renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "beta" })).rejects.toBeInstanceOf(InvalidSlugError);
    await expect(orgService.renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "admin" })).rejects.toBeInstanceOf(InvalidSlugError);

    const t0 = Date.now();
    const renamed = await orgService.renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "alpha-two" });
    expect(renamed).toEqual({ ...a.org, slug: "alpha-two" });
    expect(seen).toEqual([expect.objectContaining({ orgId: a.org.id, actorId: a.userIds.admin, from: "alpha", to: "alpha-two" })]);
    expect((await orgService.resolveOrgBySlug("alpha"))?.slug).toBe("alpha-two");
    expect((await orgService.getOrganizationSummary(a.actors.owner, a.org.id)).organization.slug).toBe("alpha-two");
    expect((await orgService.listOrganizationsForUser(a.userIds.owner)).map((o) => o.slug)).toContain("alpha-two");
    const principal = { userId: a.userIds.member, email: "x", activeOrgId: null, expiresAt: "2099-01-01T00:00:00.000Z" } as never;
    expect((await sessionService.resolveActorForOrg(principal, "alpha"))?.orgId).toBe(a.org.id);
    await expect(orgService.renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "alpha" })).rejects.toBeInstanceOf(InvalidSlugError);
    const created = await orgService.createOrganization(b.userIds.owner, { name: "x", slug: "alpha", plan: "free" });
    expect(created.slug).toBe("alpha-2");

    const page = await activityService.listActivity(a.actors.owner, { orgId: a.org.id, action: ["organization.slug_changed"], limit: 25, cursor: null });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({ subjectKind: "organization", subjectId: a.org.id, metadata: { from: "alpha", to: "alpha-two" } });

    // chain + back
    await orgService.renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "alpha-three" });
    expect((await orgService.resolveOrgBySlug("alpha"))?.id).toBe(a.org.id);
    expect((await orgService.resolveOrgBySlug("alpha-two"))?.id).toBe(a.org.id);
    await orgService.renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "alpha" });
    expect((await orgService.resolveOrgBySlug("alpha-three"))?.id).toBe(a.org.id);

    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(t0 + ORG_SLUG_HOLD_DAYS * 86400000 - 60000);
    expect((await orgService.resolveOrgBySlug("alpha-two"))?.id).toBe(a.org.id);
    vi.setSystemTime(Date.now() + 10 * 60000);
    expect(await orgService.resolveOrgBySlug("alpha-two")).toBeNull();
    expect(await sessionService.resolveActorForOrg(principal, "alpha-two")).toBeNull();
    expect((await orgService.resolveOrgBySlug("alpha-three"))?.id).toBe(a.org.id);
    const took = await orgService.renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "alpha-two" });
    expect(took.slug).toBe("alpha-two");
    vi.useRealTimers();
    off();
  });
});
